"""Code of Virginia: the Virginia Law Library's per-title CSV files (law.lis.virginia.gov/CSV/CoVTitle_N.csv, linked from /law-library/) — 72 requests for the whole code. One row per section; where a section has two texts (effective until / effective from, contingent), the one in force today."""
import csv, datetime, io, re
B = "https://law.lis.virginia.gov"
csv.field_size_limit(1 << 30)
MONTHS = {m: i for i, m in enumerate(["january", "february", "march", "april", "may", "june", "july", "august",
                                       "september", "october", "november", "december"], 1)}
NOTE = re.compile(r"^\s*\(([^)]*)\)\s*")

def when(note):
    m = re.search(r"([A-Za-z]+) (\d{1,2}), (\d{4})", note)
    if m and m.group(1).lower() in MONTHS:
        return datetime.date(int(m.group(3)), MONTHS[m.group(1).lower()], int(m.group(2)))

def in_force(note, today):
    """True/False for a version note: (Effective until July 1, 2026), (Effective July 1, 2026), (For contingent ...)."""
    low = note.lower(); d = when(note)
    if "until" in low or "expiration" in low:
        return d is None or d > today
    if "effective" in low:
        return d is not None and d <= today
    return None

def sections():
    today = datetime.date.today()
    kind, lib = fetch(B + "/law-library/")
    files = []
    for f in re.findall(r"href='(/CSV/CoVTitle_[0-9A-Za-z.]+\.csv)'", lib):
        if f not in files:
            files.append(f)
    log("titles: %d" % len(files))
    for f in files:
        url = B + f
        kind, body = fetch(url)
        rows = list(csv.DictReader(io.StringIO(body.lstrip("﻿"))))
        by = {}
        for r in rows:
            by.setdefault(r["Section"].strip(), []).append(r)
        n = 0
        for sid, vs in by.items():
            pick = vs[0]
            if len(vs) > 1:
                ok = [v for v in vs if in_force((NOTE.match(v["Title"]) or [None, ""])[1], today)]
                pick = ok[0] if ok else vs[0]
                if not ok:
                    log("%s: %d versions, none plainly in force today — kept the first" % (sid, len(vs)))
            heading = NOTE.sub("", pick["Title"]).strip() if len(vs) > 1 else pick["Title"].strip()
            text = block_text("<div class='b'>" + pick["Body"] + "</div>", cls="b")
            if not sid or not text:
                continue
            n += 1
            yield {"id": sid, "heading": heading, "text": text, "url": url + "#" + sid}
        log("%s: %d sections (%d rows)" % (f.rsplit("/", 1)[-1], n, len(rows)))
